    }
    protected override void Update(GameTime time){CrashDiagnostics.Phase="Atualizando partida";using var profileUpdate=ProfileSample(true);PublishEnemyMonitor();ClampCamera();inventionClock+=Math.Clamp(time.ElapsedGameTime.TotalSeconds,0,.1);originalAudio?.Update();var k=Keyboard.GetState();var m=Mouse.GetState();if(marketMenu||testMenu||pauseMenu.Open||researchMenu||constructionMenu||simulation.MissionWon)CancelPointerNavigation();if(!IsActive){marketQuantityRepeat.Reset();CancelPointerNavigation();resourceGesture.Cancel();dragStart=null;oldKeys=k;oldMouse=m;base.Update(time);return;}
        if(!marketMenu&&!testMenu&&!pauseMenu.Open&&!researchMenu&&!constructionMenu&&!ResearchMovieOpen&&!simulation.MissionWon&&UpdateTradeShortcut(m)){oldKeys=k;oldMouse=m;base.Update(time);return;}
        if(marketMenu){UpdateMarket(k,m);AdvanceSimulation();oldKeys=k;oldMouse=m;base.Update(time);return;}
        StartResearchMovie();if(ResearchMovieOpen){UpdateResearchMovie(time,k,m);oldKeys=k;oldMouse=m;base.Update(time);return;}
        if(testMenu){UpdateTestMenu(k,m);oldKeys=k;oldMouse=m;base.Update(time);return;}
        bool ctrlHeld=capture!=null&&captureMenu=="resource-order"||k.IsKeyDown(Keys.LeftControl)||k.IsKeyDown(Keys.RightControl);if(!ctrlHeld&&resourceGesture.Pending){resourceGesture.Cancel();message="Escolha cancelada; ordem anterior preservada.";}
        if(pauseMenu.Open){CancelPointerNavigation();UpdateMenu(k,m);oldKeys=k;oldMouse=m;base.Update(time);return;}
        if(simulation.MissionWon){UpdateMissionComplete(k,m);oldKeys=k;oldMouse=m;base.Update(time);return;}
