    void Text(string s,int x,int y,Color? color=null,float scale=1){batch.DrawString(font,s,new Vector2(x,y),color??Color.White,0,Vector2.Zero,scale,SpriteEffects.None,0);}
    void Outline(Rectangle r,Color c,int n=1){batch.Draw(white,new Rectangle(r.X,r.Y,r.Width,n),c);batch.Draw(white,new Rectangle(r.X,r.Bottom-n,r.Width,n),c);batch.Draw(white,new Rectangle(r.X,r.Y,n,r.Height),c);batch.Draw(white,new Rectangle(r.Right-n,r.Y,n,r.Height),c);}
    void Command(DrawCommand c,float x=0,float y=0,bool gray=false,int owner=0){
        if(!sprites.TryGetValue(c.Sprite,out var t))return;
        if(c.Kind is "player" or "unit")t=PlayerTexture(c.Sprite,t,owner);if(gray&&c.Kind!="shadow")t=GrayTexture(c.Sprite+owner*20000,t);
        int left=0,top=0,right=t.Width,bottom=t.Height;
        if(c.Clip is {} clip){left=Math.Max(0,clip.Left-c.X);top=Math.Max(0,clip.Top-c.Y);right=Math.Min(t.Width,clip.Right-c.X+1);bottom=Math.Min(t.Height,clip.Bottom-c.Y+1);}
        if(right<=left||bottom<=top)return;
        var p=ToScreen(c.X+x+left,c.Y+y+top);if(p.X+(right-left)*zoom<0||p.X>ViewWidth||p.Y+(bottom-top)*zoom<Top||p.Y>Top+ViewHeight)return;
        Color color=c.Kind=="shadow"?new Color(0,0,0,80):Color.White;batch.Draw(t,p,new Rectangle(left,top,right-left,bottom-top),color,0,Vector2.Zero,zoom,SpriteEffects.None,0);
    }
