        if(capture!=null&&draws==(profileRun?150:captureArcher?70:captureCombat?95:captureBuild?600:captureFood?600:captureWalk?40:5)){int width=GraphicsDevice.PresentationParameters.BackBufferWidth,height=GraphicsDevice.PresentationParameters.BackBufferHeight;var colors=new Color[width*height];GraphicsDevice.GetBackBufferData(colors);using var t=new Texture2D(GraphicsDevice,width,height);t.SetData(colors);Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(capture))!);using var f=File.Create(capture);t.SaveAsPng(f,width,height);WriteProfile();Exit();}base.Draw(time);
